const button=(label,href,light=false)=>`<a class="btn ${light?'light':''}" href="${href}"${href.startsWith('mailto:')?' data-stewart-chat':''}>${label} ↗</a>`;
const intro=(tag,title,copy)=>`<div class="subhero"><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${copy}</p></div>`;
const featured=`<div class="sectionhead"><div><div class="eyebrow">A place for your next chapter</div><h2>Haley’s listings, first.</h2></div>${button('Explore all homes','homes.html',true)}</div><div id="listings" aria-live="polite"><div class="notice"><h3>Let’s find what feels like home.</h3><p>Ask Haley about her current listings, or explore available properties through Baldwin REALTORS®.</p>${button('Ask about Haley’s listings','mailto:haleymontgomery.realty@gmail.com?subject=Your%20current%20listings')} <p class="muted">Live property listings are not yet connected to this website. Availability and prices should be confirmed with Haley.</p></div></div>`;
const communities=`<div class="sectionhead"><div><div class="eyebrow">South Alabama, close to home</div><h2>Find your kind of everyday.</h2></div></div><div class="grid places"><a href="${SEARCH}"><span class="eyebrow">Bayside living</span><h3>Fairhope & Daphne</h3><span>Explore homes ↗</span></a><a href="${SEARCH}"><span class="eyebrow">Room to settle in</span><h3>Spanish Fort & Loxley</h3><span>Explore homes ↗</span></a><a href="${SEARCH}"><span class="eyebrow">Life near the coast</span><h3>Foley & the beaches</h3><span>Explore homes ↗</span></a></div><p class="muted">Bayside Living: Fairhope Pier, photo by <a href="https://commons.wikimedia.org/wiki/File:Fairhope_Pier_Sept_2012.jpg">Chris Pruitt</a>, <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a> (cropped for display). Room to settle in: <a href="https://www.realtor.com/realestateandhomes-detail/34360-Steelwood-Ridge-Rd_Loxley_AL_36551_M88896-75395">Steelwood lakefront neighborhood, Loxley</a>. Community photographs illustrate the area and do not indicate properties listed by Haley. The beach image is regional lifestyle imagery. Links open the Baldwin REALTORS® property search.</p>`;
const pages={
index:`<div class="hero"><div><div class="eyebrow">Montgomery & Co. · South Alabama Real Estate</div><h1>A new chapter.<br>A place to call home.</h1><p>Local knowledge. A listening ear. Thoughtful guidance for wherever life takes you next.</p>${button('Find your home','homes.html')}</div><span class="photo-note">Craftsman home in Fairhope · illustrative photo</span></div><div class="searchbar"><div><strong>Your South Alabama home search starts here.</strong><span>From the Eastern Shore to the Gulf Coast.</span></div>${button('Search Baldwin REALTORS®',SEARCH)}</div><section>${featured}</section><section class="soft split"><div><div class="eyebrow">Meet your broker</div><h2>Hi, I’m Haley.<br>I’m glad you’re here.</h2><p>I’m the broker and owner of Montgomery & Co., serving South Alabama with 11 years in the industry. I work with buyers, sellers, investors, first-time buyers, veterans, and retirees.</p><p>Every move is personal. I’ll take the time to understand yours, answer your questions, and help you feel confident about what comes next.</p>${button('Get to know Haley','broker.html',true)}</div><img class="scene" src="https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1000&q=85" alt="Bright living room with warm, natural details" loading="lazy"></section><section>${communities}</section><section class="dark"><div class="eyebrow">Thoughtful guidance, every step</div><h2>Your goals. Your pace.<br>A partner in your corner.</h2><div class="chips"><span>Buying your first home</span><span>Selling & moving forward</span><span>Investing</span><span>Veterans</span><span>Retirement & relocation</span></div>${button('Let’s talk about your move','mailto:haleymontgomery.realty@gmail.com')}</section><section><div class="eyebrow">Kind words from clients</div><blockquote>“Haley was an amazing realtor!”</blockquote><p>Rawan Nasir · Zillow · October 7, 2024</p>${button('Read client stories','testimonials.html',true)}</section>`,
homes:intro('Find a home','Your next chapter starts here.','Explore South Alabama homes, with personal guidance from Haley from the first showing to the closing table.')+`<section>${featured}</section><section class="soft"><div class="eyebrow">Explore the market</div><h2>More homes. One local resource.</h2><p>Browse available homes, coming-soon properties, new construction, and homes under contract on Baldwin REALTORS®. Haley can help you understand each property’s status and arrange a showing.</p>${button('Browse Baldwin REALTORS®',SEARCH)} ${button('Contact Haley','mailto:haleymontgomery.realty@gmail.com',true)}</section><section>${communities}</section>`,
broker:intro('Meet the broker','Hi, I’m Haley Montgomery.','South Alabama real estate, with a personal touch.')+`<section class="split"><div><div class="eyebrow">Broker & Owner · Montgomery & Co.</div><h2>People first.<br>Every move.</h2><p>I’ve spent 11 years in this industry, and what I enjoy most is helping people move into their next chapter with a little more clarity and confidence.</p><p>Whether you’re buying your first home, selling a place full of memories, investing, or planning for retirement, I’ll listen to what matters to you and help you take the next step.</p><p>I work with buyers, sellers, investors, first-time buyers, veterans, and retirees across South Alabama. You can expect honest conversations, attentive communication, and room to ask every question.</p>${button('Let’s connect','mailto:haleymontgomery.realty@gmail.com')}<p><a href="tel:+12513080016">(251) 308-0016</a></p></div><div class="soft card"><div class="eyebrow">A note from Haley</div><blockquote>“Every move is personal. Let’s talk about what yours looks like.”</blockquote><p>Haley Montgomery<br>Broker & Owner, Montgomery & Co.</p><a href="${ZILLOW}">View Haley’s Zillow profile ↗</a></div></section>`,
agents:intro('Meet the agents','Local people. Personal guidance.','Meet Montgomery & Co. and find the right person to help with your next move.')+`<section><div class="grid">${[['HM','Haley Montgomery','Broker & Owner'],['TG','Timothy Gruzs','Agent'],['PW','Paityn Webb','Agent'],['DT','Darren Thomas','Agent']].map(([initial,name,role])=>`<article class="card"><div class="avatar">${initial}</div><h3>${name}</h3><div class="eyebrow">${role}</div><p>Montgomery & Co., LLC</p><a href="${OFFICE}">View brokerage directory ↗</a></article>`).join('')}</div><p class="muted">Team names sourced from the Baldwin REALTORS® brokerage directory. Confirm the current roster with the brokerage.</p>${button('Find your agent',OFFICE,true)}</section>`,
about:intro('About us','Real estate is about people.','A home is part of your story. We’re here to help you take the next step with care.')+`<section class="split"><div><div class="eyebrow">Montgomery & Co.</div><h2>Rooted in South Alabama.<br>Focused on you.</h2><p>Led by broker and owner Haley Montgomery, Montgomery & Co. helps buyers and sellers navigate real estate with personal attention and clear communication.</p><p>From the Eastern Shore to the Gulf Coast, we help you explore your options, understand the process, and make decisions that fit your goals.</p>${button('Meet our team','agents.html',true)}</div><img class="scene" src="https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1000&q=85" alt="Inviting, sunlit home interior" loading="lazy"></section><section class="soft"><div class="eyebrow">What you can expect</div><h2>A thoughtful approach to your move.</h2><div class="grid"><article class="card"><span class="num">01 / LISTEN</span><h3>Start with your story.</h3><p>We take time to understand your priorities, timing, and questions.</p></article><article class="card"><span class="num">02 / UNDERSTAND</span><h3>Make room for clarity.</h3><p>We talk through your options so you can make informed decisions.</p></article><article class="card"><span class="num">03 / MOVE FORWARD</span><h3>Take the next step.</h3><p>Attentive guidance through your search, offer, negotiations, and closing.</p></article></div></section>`,
testimonials:intro('Client stories','The people behind the moves.','Read about working with Haley, in her clients’ own words.')+`<section><div class="review-tabs" role="tablist" aria-label="Review source"><button id="tab-zillow" role="tab" aria-selected="true" aria-controls="reviews">Zillow</button><button id="tab-facebook" role="tab" aria-selected="false" aria-controls="reviews">Facebook</button></div><div id="reviews" role="tabpanel" aria-labelledby="tab-zillow"></div></section>`
};
pages.register="<div class=\"subhero\"><div class=\"eyebrow\">Your home search · with Stewart</div><h1>Tell us what home<br>looks like for you.</h1><p>A few details help Haley send you useful property information and understand what matters most in your search.</p></div><section class=\"register-layout\"><aside><h2>A search that fits you.</h2><p>Share your budget, favorite areas, home preferences, and timing. You can also let Haley know if you’d like a call.</p><div class=\"card peach\"><h3>Personal guidance.</h3><p>This is a home-search registration, not a mortgage application. Please don’t include Social Security numbers, passwords, or financial documents.</p><a href=\"tel:+12513080016\">Call (251) 308-0016</a></div><p class=\"muted\">Your answers are collected by Jotform and shared with Haley Montgomery at Montgomery & Co. for your inquiry. Select how you’d like to be contacted in the form.</p></aside><div><iframe id=\"buyer-form\" class=\"buyer-form\" title=\"Home search registration with Haley Montgomery\" src=\"https://form.jotform.com/263067043487057\" loading=\"lazy\"></iframe><p><a href=\"https://form.jotform.com/263067043487057\" target=\"_blank\" rel=\"noopener\">Open the registration form in a new tab ↗</a></p><p class=\"muted\">Already submitted in another tab? Call or text Haley if you need help continuing your search.</p></div></section>";
pages.stewart="<div class=\"subhero\"><div class=\"eyebrow\">Montgomery & Co. · Assistant workspace</div><h1>Meet Stewart.</h1><p>Your website and real estate communication assistant. Warm, personable, professional, and focused on helping people connect with Haley.</p></div><section><div class=\"notice\"><strong>Monitoring scheduled · Google access verified</strong><p>Google Voice and Gmail access for haleymontgomery.realty@gmail.com and source number (251) 308-0016 were verified on November 3, 2026. Hourly and active-conversation checks are scheduled. No test messages were sent; future replies depend on this computer, Codex, and the signed-in browser remaining available.</p><p>This dashboard shows the saved setup, not a live inbox. Message history and delivery records are kept separately in Stewart’s private local records.</p></div><div class=\"grid\" style=\"margin-top:25px\"><article class=\"card peach\"><div class=\"eyebrow\">When quiet</div><h3>Every hour</h3><p>Check for new inquiries in text, voicemail, and email. Ignore the existing unread backlog when first connected.</p></article><article class=\"card blue\"><div class=\"eyebrow\">During a conversation</div><h3>Every 15 minutes</h3><p>Switch to frequent checks after an inquiry. Return to hourly checks when the conversation ends or the person hasn’t responded for 30 minutes.</p></article><article class=\"card gold\"><div class=\"eyebrow\">Keep Haley informed</div><h3>Every new message</h3><p>Email haleymontgomery.realty@gmail.com with the sender, inquiry, reply, callback preference, and next step. Google account access is verified; each future delivery will be checked and logged.</p></article></div></section><section class=\"soft split\"><div><div class=\"eyebrow\">Stewart’s conversation goal</div><h2>A helpful next step.</h2><p>“Hi, I’m Stewart, Haley’s virtual assistant with Montgomery & Co. Are you looking to buy, sell, or learn about a property?”</p><p>“Would you like Haley to give you a call, or would you prefer to start with the website?”</p><p>Ask one or two useful questions at a time. Record the person’s name, preferred contact method, property interests, budget, and timing when they choose to share them. Don’t make availability or appointment promises.</p></div><div class=\"card\"><h3>Quick access</h3><p><a href=\"https://voice.google.com/\" target=\"_blank\" rel=\"noopener\">Open Google Voice ↗</a></p><p><a href=\"https://mail.google.com/\" target=\"_blank\" rel=\"noopener\">Open Gmail ↗</a></p><p><a href=\"https://www.jotform.com/build/263067043487057\" target=\"_blank\" rel=\"noopener\">Manage buyer registration ↗</a></p><p><a href=\"register.html\">Preview buyer registration ↗</a></p><p class=\"muted\">Choose Haley’s account in Google. These links open the services; they do not connect them automatically.</p></div></section><section><div class=\"eyebrow\">Schedule preview</div><h2>How Stewart changes pace.</h2><label for=\"schedule-state\">Choose a conversation state</label><select id=\"schedule-state\"><option value=\"idle\">No active conversation</option><option value=\"active\">New message / active conversation</option><option value=\"timeout\">No response for 30 minutes</option><option value=\"closed\">Conversation ended</option></select><p id=\"schedule-result\" aria-live=\"polite\">Next channel check: hourly. This preview does not change the saved monitor.</p><p class=\"muted\">Periodic checks depend on Codex running and Google login remaining available. Website links are for review only while the site remains private.</p></section>";
const faqContent="<section class=\"soft faq-section\"><div class=\"eyebrow\">Helpful answers</div><h2>South Alabama real estate questions</h2><details><summary>Where does Montgomery & Co. help buyers and sellers?</summary><p>Montgomery & Co. serves South Alabama, including Fairhope, Daphne, Spanish Fort, Loxley, Foley, Gulf Shores, and Orange Beach. Contact Haley Montgomery to discuss your preferred area and next move.</p></details><details><summary>Who is the broker at Montgomery & Co.?</summary><p>Haley Montgomery is the broker and owner of Montgomery & Co. She has 11 years of real estate industry experience and works with buyers, sellers, investors, first-time buyers, veterans, and retirees.</p></details><details><summary>How can I find homes for sale in Baldwin County?</summary><p>Use the Find a Home page to open the Baldwin REALTORS® property search. Contact Haley to confirm availability, discuss your priorities, and arrange a showing. Live MLS listings are not yet connected to this website.</p></details><details><summary>Can Haley help first-time buyers, veterans, and retirees?</summary><p>Yes. Haley works with first-time buyers, veterans, and retirees, as well as sellers and investors. She can help you explore homes, understand the buying or selling process, and plan your next steps.</p></details><details><summary>How do I contact Haley Montgomery?</summary><p>Call or text (251) 308-0016 or email haleymontgomery.realty@gmail.com to talk about buying, selling, or investing in South Alabama.</p></details><p><a href=\"homes.html\">Explore homes</a> · <a href=\"broker.html\">Meet Haley</a> · <a href=\"testimonials.html\">Read client stories</a></p></section>";
pages.index+=faqContent;
pages.homes+=faqContent;
if(!document.getElementById('app').hasChildNodes())document.getElementById('app').innerHTML=`<header><a class="brand" href="index.html"><img class="brand-logo" src="assets/montgomery-co-logo.png" alt="Montgomery & Co. Real Estate" width="843" height="825"></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation">${links.slice(1).map(([slug,label])=>`<a href="${slug}.html" ${page===slug?'aria-current="page"':''}>${label}</a>`).join('')}<a href="tel:+12513080016">Let’s talk ↗</a></nav></header><main>${pages[page]||pages.index}</main><a class="chat-button" href="register.html" data-stewart-chat aria-label="Chat with Stewart, Haley’s virtual assistant">Let’s Chat</a><footer><div class="footgrid"><div><a class="brand" href="index.html"><img class="brand-logo footer-logo" src="assets/montgomery-co-logo.png" alt="Montgomery & Co. Real Estate" width="843" height="825" loading="lazy"></a><p>Thoughtful real estate guidance.<br>South Alabama, from the bay to the beach.</p><a href="mailto:haleymontgomery.realty@gmail.com">haleymontgomery.realty@gmail.com</a><a href="tel:+12513080016">(251) 308-0016</a></div><div><strong>Explore</strong>${links.slice(1).map(([slug,label])=>`<a href="${slug}.html">${label}</a>`).join('')}</div><div><strong>Stay connected</strong><a href="${FACEBOOK}">Facebook ↗</a><a href="${ZILLOW}">Zillow ↗</a><a href="${OFFICE}">Baldwin REALTORS® ↗</a></div></div><div class="bottom"><span>© ${new Date().getFullYear()} Montgomery & Co., LLC</span><span>Equal Housing Opportunity · All are welcome.</span></div></footer>`;
document.querySelector('.menu').onclick=e=>{const open=document.querySelector('nav').classList.toggle('open');e.target.setAttribute('aria-expanded',open)};
function showReviews(source){document.querySelectorAll('[role=tab]').forEach(b=>b.setAttribute('aria-selected',b.id===`tab-${source}`));const el=document.getElementById('reviews');el.setAttribute('aria-labelledby',`tab-${source}`);el.innerHTML=source==='zillow'?`<article class="card"><div class="eyebrow">Zillow · Client review excerpt</div><blockquote>“Haley was an amazing realtor!”</blockquote><p>Rawan Nasir · Bought a home in Daphne · October 7, 2024</p><a href="${ZILLOW}">Read the full review on Zillow ↗</a></article><p class="muted">This is a manually sourced excerpt. Automatic Zillow review updates are not connected yet.</p>`:`<article class="card"><div class="eyebrow">Facebook recommendations</div><h3>More client stories on Facebook.</h3><p>Visit Haley’s business page to read recommendations and connect with her.</p>${button('Visit Haley on Facebook',FACEBOOK)}<p class="muted">Automatic Facebook review updates are not connected yet.</p></article>`}
if(page==='testimonials'){showReviews('zillow');document.querySelectorAll('[role=tab]').forEach(b=>b.onclick=()=>showReviews(b.id.replace('tab-','')))}
// Connect a licensed, same-origin listing adapter at this URL. An empty URL means disconnected.
async function loadListings(){const config=await fetch('integrations.json').then(r=>r.json());if(!config.listingsFeedUrl||!document.getElementById('listings'))return;try{const response=await fetch(config.listingsFeedUrl);if(!response.ok)throw Error('Feed unavailable');const data=await response.json();const active=data.listings.filter(x=>x.status==='Active').sort((a,b)=>Number(b.haleyListing)-Number(a.haleyListing));if(!active.length)return;const grid=document.createElement('div');grid.className='grid';for(const listing of active){const card=document.createElement('article');card.className='card';const tag=document.createElement('span');tag.className='eyebrow';tag.textContent=listing.haleyListing?'Listed by Haley':'Available home';const title=document.createElement('h3');title.textContent=listing.address;const details=document.createElement('p');details.textContent=`${new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(listing.price)} · ${listing.beds} beds · ${listing.baths} baths`;const link=document.createElement('a');const url=new URL(listing.url,location.href);if(!['http:','https:'].includes(url.protocol))continue;link.href=url.href;link.dataset.propertyId=String(listing.id||url.href);link.target='_blank';link.rel='noopener';link.textContent='View property ↗';card.append(tag,title,details,link);grid.append(card)}if(grid.children.length)document.getElementById('listings').replaceChildren(grid)}catch{ /* Keep the honest disconnected fallback when the feed is unavailable. */ }}
loadListings().catch(()=>{});
